import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";
import "./style/Comparison.css";

const BASE_URL = "https://salam29.pythonanywhere.com";
const ENDPOINTS = {
  "الخوارزمية الجينية (GA)": "/api/ga",
  "GA + Mutual Information": "/api/ga_mi",
  "GA + PCA": "/api/ga_pca",
  "GA + RFE": "/api/ga_rfe",
  "GA + Chi-Square": "/api/ga_chi",
};

function Comparison() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const promises = Object.entries(ENDPOINTS).map(async ([name, endpoint]) => {
          try {
            const res = await fetch(`${BASE_URL}${endpoint}`);
            const data = await res.json();

            const accuracy =
              data.accuracy ??
              data.model_accuracy ??
              data.best_fitness ??
              data.fitness ??
              data.fitness_score ??
              null;

            const numFeatures =
              data.num_selected ??
              data.num_selected_features ??
              data.selected_features_count ??
              null;

            return {
              method: name,
              accuracy: accuracy
                ? Number((accuracy * (accuracy <= 1 ? 100 : 1)).toFixed(2))
                : null,
              features: numFeatures ?? "غير متاح",
            };
          } catch (e) {
            console.warn(`⚠️ خطأ في ${name}:`, e);
            return { method: name, accuracy: null, features: "خطأ في التحميل" };
          }
        });

        const allResults = await Promise.all(promises);
        setResults(allResults);
      } catch (err) {
        console.error("خطأ أثناء جلب البيانات:", err);
        setError("تعذّر تحميل نتائج المقارنة.");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const colors = ["#be185d", "#ec4899", "#f472b6", "#f9a8d4", "#fbcfe8"];

  return (
    <div className="comparison-container">
      <h1 className="comparison-title">مقارنة بين طرق اختيار الخصائص</h1>

      <p className="comparison-description">
        يوضح الجدول والمخطط أدناه نتائج الطرق المختلفة لاختيار الخصائص من الخادم. كل طريقة تُظهر عدد الخصائص المختارة ودقّة النموذج.
      </p>

      {loading ? (
        <p className="loading-text">⏳ جارٍ تحميل النتائج...</p>
      ) : error ? (
        <p className="error-text">{error}</p>
      ) : (
        <>
          {/* جدول المقارنة */}
          <table className="comparison-table">
            <thead>
              <tr>
                <th>الطريقة</th>
                <th>عدد الخصائص المختارة</th>
                <th>دقة النموذج</th>
              </tr>
            </thead>
            <tbody>
              {results.map((row, index) => (
                <tr key={index}>
                  <td style={{ fontWeight: "bold", color: colors[index % colors.length] }}>
                    {row.method}
                  </td>
                  <td>{row.features}</td>
                  <td>{row.accuracy !== null ? `${row.accuracy}%` : "غير متاح"}</td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* الرسم البياني */}
          <h2 style={{ color: "#be185d", marginTop: "40px" }}>
            التمثيل البياني لدقة النماذج
          </h2>

          <ResponsiveContainer width="90%" height={400}>
            <BarChart
              data={results.filter((r) => r.accuracy !== null)}
              margin={{ top: 20, right: 30, left: 20, bottom: 10 }}
            >
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="method" tick={{ fontSize: 12 }} />
              <YAxis />
              <Tooltip
                formatter={(value, name, props) => [
                  `${value}%`,
                  `الدقة - ${props.payload.features} خصائص`,
                ]}
                contentStyle={{
                  backgroundColor: "#fff0f6",
                  border: "1px solid #f9a8d4",
                  borderRadius: "8px",
                }}
              />
              <Bar dataKey="accuracy" radius={[10, 10, 0, 0]}>
                {results.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={colors[index % colors.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </>
      )}

      <button onClick={() => navigate("/results")} className="comparison-btn">
        العودة إلى النتائج
      </button>
    </div>
  );
}

export default Comparison;
